/** 已内置图标的品牌名单（供测试断言"新客户端别忘了配图标"）。 */
export const BRAND_NAMES = Object.keys(BRAND_ART) as BrandName[];

/** 是否有内置 logo。Hub 连接上报的 client 是任意字符串（未知客户端归为
 *  `custom`），渲染前必须先过这一关，否则 `as BrandName` 断言会把它送进
 *  查不到图的分支。 */
export const isBrandName = (value: string): value is BrandName => Object.hasOwn(BRAND_ART, value);

/** `muted`：未安装态去色。调用点改 currentColor 只管得住单色 logo，
 *  原色 logo（OpenClaw 龙虾）颜色写死在 path 里，得靠滤镜。 */
export function BrandGlyph({
  name,
  size = 20,
  muted = false,
}: {
  name: BrandName;
  size?: number;
  muted?: boolean;
}) {
  const art = BRAND_ART[name];
  // 名字来自 `as BrandName` 断言时可能落空（见 isBrandName）：没有图就不画，
  // 而不是让下面的取值链在 undefined 上炸掉整页。
  if (!art) return null;

  // 位图 logo：图案本体当 mask，底色取 currentColor，跟 IconChip 的色调走。
  if (typeof art === "object" && !Array.isArray(art) && "mask" in art) {
    const mask = `url(${art.mask}) center / contain no-repeat`;
    return (
      <span
        aria-hidden="true"
        style={{
          display: "inline-block",
          flexShrink: 0,
          width: size,
          height: size,
          backgroundColor: "currentColor",
          WebkitMask: mask,
          mask,
        }}
      />
    );
  }

  const [viewBox, children] =
    typeof art === "object" && !Array.isArray(art)
      ? [art.viewBox, art.markup]
      : [
          "0 0 24 24",
          (Array.isArray(art) ? art : [art]).map((d) => <path key={d.slice(0, 16)} d={d} />),
        ];

  return (
    <svg
      width={size}
      height={size}
      viewBox={viewBox}
      fill="currentColor"
      aria-hidden="true"
      style={muted ? { filter: "grayscale(1)" } : undefined}
    >
      {children}
    </svg>
  );
}

/**
 * 形态角标：Claude Code 与 Claude Desktop 共用 Anthropic 的同一个 logo，并排时
 * 只看图形分不出是哪一个（客户端页的卡片就被看漏过）。终端 = CLI，显示器 = 桌面应用。
 *
 * 只有 `ClientMeta.surface` 有值的客户端才渲染——其余 logo 本身唯一，全都标反而是噪音。
 * 定位是绝对定位，调用点的容器需自带 `relative`；`className` 用来改角标底色，
 * 让它在不同底色（卡片白底 / 页签灰底）上都像一片浮起的小标。
 */
export function SurfaceBadge({
  app,
  size = 11,
  className,
}: {
  /** 客户端 id：`ClientApp` 或客户端页的 MCP 客户端 id 均可。 */
  app: string;
  size?: number;
  className?: string;
}) {
  const surface = surfaceOf(app);
  if (!surface) return null;
  const Icon = surface === "gui" ? Monitor : Terminal;
  return (
    <span
      aria-hidden
      style={{ width: size, height: size }}
      className={cn(
        "-right-1 -bottom-1 absolute inline-flex items-center justify-center rounded-[3px] border border-card bg-hover text-ink",
        className,
      )}
    >
      <Icon size={Math.round(size * 0.72)} strokeWidth={2.5} />
    </span>
  );
}

/**
 * 客户端图标 + 品牌色。
 *
 * `BrandGlyph` 里的单色 logo 跟随 currentColor，直接放进正文就会继承那一处的
 * 文字色——在次要文本里发灰、在选中行里变蓝，两头都不像 logo。这里按
 * `CLIENT_META.color` 上品牌色；没有识别度品牌色的（OpenAI / xAI 这类黑白 logo，
 * 表里记的是 currentColor）落到墨色。
 *
 * `tone="inherit"` 关掉上色，用于图标必须跟着底色走的场合（实心主色底上的白 logo）。
 */
export function ClientGlyph({
  app,
  size = 16,
  tone = "brand",
}: {
  app: ClientApp;
  size?: number;
  tone?: "brand" | "inherit";
}) {
  const { color } = CLIENT_META[app];
  const branded = tone === "brand" && color !== "currentColor";
  return (
    <span
      aria-hidden
      className={cn("flex shrink-0", tone === "brand" && !branded && "text-ink")}
      style={branded ? { color } : undefined}
    >
      <BrandGlyph name={app} size={size} />
    </span>
  );
}
